      SUBROUTINE UNITS(J)CC     MAKES UNITS CHANGESCC ----------------------------------------------------------------------      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'UMAD.CIN'      INCLUDE 'UMETER.CIN'      INCLUDE 'UMICR.CIN'      INCLUDE 'UMM.CIN'      INCLUDE 'UORIG.CIN'      INCLUDE 'UTRANS.CIN'      INCLUDE 'XMAD.CIN'      INCLUDE 'XMETER.CIN'      INCLUDE 'XMICR.CIN'      INCLUDE 'XMM.CIN'      INCLUDE 'XORIG.CIN'      INCLUDE 'XTRANS.CIN'C ----------------------------------------------------------------------      CHARACTER*4     UTABLE(19)      LOGICAL         INPUT, OUTPUT, ELEMEN, BEAM, FLOOR, ALIGN      REAL            CTABLE(19)C      DATA NUNIT /19/, NUNITS /14/      DATA UTABLE /'M' , 'CM' ,  'MM' , 'MICR', 'IN', 'FT' ,     1             'R' , 'MR' ,  'MUR', 'DEG',  'N',  'PC' ,     2             'PM', 'PMIC', 'GEV', 'MEV',  'KG', 'G'  ,     3             'TUNE' /      DATA CTABLE / 1.0, 0.01, 0.001, 1.E-6, .0254, .3048,     1              1.0, 0.001, 1.E-6, 0.0, 1.0, 0.01,     2              0.001, 1.E-6, 1.0, 0.001, 1.0, 0.001,     3              0.0 /CC     DETERMINE WHICH UNITS ARE TO BE CHANGEDC      CTABLE(19) = 2.0*PI      IF (J .GE. 82 .AND. J .LE. 86) GO TO 300      IF (J .GT. NUNITS) GO TO 400      IF (J .EQ. 0) GO TO 300      INPUT = IPTOJ(3) .GE. 1      OUTPUT = IPTOJ(4) .GE. 1      IF (.NOT. INPUT .AND. .NOT. OUTPUT) THEN        INPUT = .TRUE.        OUTPUT = .TRUE.      ENDIF      ELEMEN = IPTOJ(5) .GE. 1      BEAM = IPTOJ(6) .GE. 1      FLOOR = IPTOJ(7) .GE. 1      ALIGN = IPTOJ(8) .GE. 1      IF (J .LE. 2 .AND. .NOT. ELEMEN .AND. .NOT. BEAM .AND.     1    .NOT. ALIGN) THEN        ELEMEN = .TRUE.        BEAM = .TRUE.        ALIGN = .TRUE.      ENDIF      IF (J .GE. 3 .AND. J .LE. 6 .AND. .NOT. ELEMEN .AND. .NOT. BEAM)     1    THEN        ELEMEN = .TRUE.        BEAM = .TRUE.      ENDIF      IF (J .EQ. 7 .OR. J .EQ. 8 .AND. .NOT. ELEMEN .AND. .NOT. FLOOR)     1    THEN        ELEMEN = .TRUE.        FLOOR = .TRUE.      ENDIF      IF (J .GE. 9) ELEMEN = .TRUE.CC     DETERMINE CONVERSION FACTORC      IF (USIZE .NE. 0.0) THEN        UFAC = UORIG(J)*USIZE      ELSE        DO 210 JU = 1, NUNIT        JJ = JU        IF (XNAME .EQ. UTABLE(JU)) GO TO 230  210   CONTINUE         WRITE (NOUT,9002) 9002   FORMAT ('0ERROR ON UNITS ELEMENT')        FLUSHL = .TRUE.        GO TO 400C  230   JU = JJ        IF (XNAME .EQ. 'DEG') THEN          UFAC = 1.0/RADIAN        ELSE          UFAC = CTABLE(JU)        ENDIF      ENDIFCC     CHANGE UNITS FOR PARTICULAR COORDINATE OR PARAMETERC  250 IF (ELEMEN) THEN        IF (INPUT) UNITI(J) = UFAC        IF (OUTPUT) THEN          UNITO(J) = UFAC          XDIME(J) = XNAME        ENDIF      ENDIF      IF (J .LE. 6 .AND. BEAM) THEN        UBEAM(J) = UFAC        XBEAM(J) = XNAME      ENDIF      IF (J .LE. 2 .AND. ALIGN) THEN        UMIS(J) = UFAC        XMIS(J) = XNAME      ENDIF      IF (J .EQ. 7 .AND. FLOOR) THEN        UFLOOR(2) = UFAC        XFLOOR(2) = XNAME      ENDIF      IF (J .EQ. 8 .AND. FLOOR) THEN        UFLOOR(1) = UFAC        XFLOOR(1) = XNAME      ENDIF      IF ((J .EQ. 10 .OR. J .EQ. 11) .AND. ELEMEN) THEN        IF (INPUT) UNITI(J) = UNITI(J)*10.0**10/CLIGHT        IF (OUTPUT) UNITO(J) = UNITO(J)*10.0**10/CLIGHT      ENDIFC      IF (J .LE. 2) THEN        IF (ELEMEN) THEN          IF (INPUT) UNITI(J+2) = UFAC          IF (OUTPUT) THEN            UNITO(J+2) = UFAC            XDIME(J+2) = XNAME          ENDIF        ENDIF        IF (BEAM) THEN          UBEAM(J+2) = UFAC          XBEAM(J+2) = XNAME        ENDIF      ENDIF      GO TO 400CC     RESET UNITS, EMPTY TYPE 15 CARD ENCOUNTEREDC  300 DEGREE = 1.0/RADIAN      UMAD(12) = 2.0*PI      UTRANS(7) = DEGREE      UTRANS(10) = EMASS      UTRANS(12) = DEGREE      UTRANS(13) = DEGREE      UMETER(12) = DEGREE      UMETER(13) = DEGREE      UMM(12) = DEGREE      UMM(13) = DEGREE      UMICR(12) = DEGREE      UMICR(13) = DEGREEC      IF (J .EQ. 82) THEN        DO 305 II = 1, 14        UORIG(II) = UMAD(II)  305   XORIG(II) = XMAD(II)      ELSE IF (J .EQ. 0 .OR. J .EQ. 83) THEN        DO 306 II = 1, 14        UORIG(II) = UTRANS(II)  306   XORIG(II) = XTRANS(II)      ELSE IF (J .EQ. 84) THEN        DO 307 II = 1, 14        UORIG(II) = UMETER(II)  307   XORIG(II) = XMETER(II)      ELSE IF (J .EQ. 85) THEN        DO 308 II = 1, 14        UORIG(II) = UMM(II)  308   XORIG(II) = XMM(II)      ELSE IF (J .EQ. 86) THEN        DO 309 II = 1, 14        UORIG(II) = UMICR(II)  309   XORIG(II) = XMICR(II)      ENDIFC      DO 310 II = 1, 14      UNITI(II) = UORIG(II)      UNITO(II) = UORIG(II)      XDIME(II) = XORIG(II)  310 CONTINUE      UNITI(10) = UNITI(10)*10.0**10/CLIGHT      UNITO(10) = UNITO(10)*10.0**10/CLIGHT      UNITI(11) = UNITI(11)*10.0**10/CLIGHT      UNITO(11) = UNITO(11)*10.0**10/CLIGHT      DO 320 II = 1, 6      UBEAM(II) = UORIG(II)      XBEAM(II) = XORIG(II)  320 CONTINUE      DO 330 II = 1, 2      UMIS(II) = UORIG(II)      XMIS(II) = XORIG(II)  330 CONTINUE      UFLOOR(1) = UORIG(8)      UFLOOR(2) = UORIG(7)      XFLOOR(1) = XORIG(8)      XFLOOR(2) = XORIG(7)C  400 RETURN      END